use std::str::FromStr;

use thiserror::Error;

const BUILTIN_ARROW: &str = "builtin-arrow";

/// Artwork generated by dmgez for a Finder background.
#[derive(Clone, Copy, Debug, Eq, Ord, PartialEq, PartialOrd)]
pub enum BackgroundTemplate {
	/// An original arrow on a fixed-size installer background.
	BuiltinArrow,
}

/// The configured name does not identify a supported background template.
#[derive(Clone, Copy, Debug, Eq, Error, PartialEq)]
#[error("unsupported Finder background template name")]
pub struct BackgroundTemplateError;

impl FromStr for BackgroundTemplate {
	type Err = BackgroundTemplateError;

	fn from_str(name: &str) -> Result<Self, Self::Err> {
		match name {
			BUILTIN_ARROW => Ok(Self::BuiltinArrow),
			_ => Err(BackgroundTemplateError),
		}
	}
}
